import { AREAS, INTERESTS, CATALOG, DEMO_MEMBERS } from './catalog.js';
import { DEFAULT_CARD, publicCard, rankPlans, rankRoom, roomCatalog, validateOption, canConfirm, formatTime, formatDate, nextSaturday, calendarFile } from './domain.js';
import { getIdentity, setIdentity, createDemo, createLocalRoom, getRoom, listRooms, saveRoom, updateLocal, shareLocalCard, proposeLocal, voteLocal, confirmLocal, localPreferences, rememberPreferences, clearDeviceData } from './storage.js';
import { connectFirebase, currentConnection, createCloudRoom, joinCloudRoom, watchCloudRoom, shareCloudCard, proposeCloud, voteCloud, confirmCloud, listCloudRooms, readConfig, addCloudOption } from './firebase.js';
import { extractPrivate, explainShortlist, localCapability } from './ai.js';
import { platform, nativeCall, shareText } from './native.js';
import { icon, avatar, illustration, mapMarkup, escapeHtml as e } from './visuals.js';
import { orbitMarkup, activityImage } from './discovery.js';

const root=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
if(!listRooms().length)createDemo();
const state={identity:getIdentity(),view:'home',roomId:null,persona:'alex',room:null,draft:null,note:'',capability:null,busy:false,tab:'shortlist',selected:null,explanations:[],explainedRevision:null,receipts:[],cloudRooms:[],modal:null,cloudError:null};
let stopWatching=null,toastTimer,modalFocusBefore=null;
const myId=room=>room?.local?(room.id==='sample-toronto'?state.persona:state.persona===state.identity.id?state.identity.id:room.members.some(m=>m.id===state.persona)?state.persona:state.identity.id):(currentConnection()?.uid||state.identity.id);
const myMember=room=>room?.members.find(m=>m.id===myId(room))||state.identity;
const currentRoom=()=>state.room?.local?getRoom(state.room.id):state.room;
const button=(action,label,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const statusName=room=>room.status==='confirmed'?'All set':room.proposal?'Time to weigh in':'Finding your halfway';
const readyCount=room=>room.members.filter(m=>m.card).length;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),6000);}
function errorMessage(error){return error?.code==='permission-denied'?'This room changed or you don’t have access. Refresh the room and try again.':error?.message||'Something went wrong. Please try again.';}
async function run(work){if(state.busy)return;state.busy=true;document.body.insertAdjacentHTML('beforeend','<div class="busy-overlay" aria-label="Working" role="progressbar"></div>');try{await work();}catch(error){toast(errorMessage(error));}finally{state.busy=false;document.querySelectorAll('.busy-overlay').forEach(el=>el.remove());}}
function nav(view,roomId){location.hash=view==='room'?`room/${roomId}`:view;}
async function route(){
  const previousView=state.view;
  const raw=location.hash.replace(/^#\/?/,'')||'home',[view,id]=raw.split('/');
  state.view=['home','plans','room','preferences','privacy','settings'].includes(view)?view:'home';
  if(previousView==='preferences'&&state.view!=='preferences')state.note='';
  if(state.view==='room'){
    if(id!==state.roomId){stopWatching?.();stopWatching=null;state.roomId=id;state.room=getRoom(id);state.tab='shortlist';state.selected=null;state.explanations=[];state.cloudError=null;
      if(!state.room){render();try{stopWatching=await watchCloudRoom(id,room=>{state.room=room;render();},error=>{state.cloudError=errorMessage(error);render();});}catch(error){state.cloudError=errorMessage(error);}}
    }
  }
  if(state.view==='preferences'){
    const room=currentRoom();state.draft=structuredClone(room?.members.find(m=>m.id===myId(room))?.card||localPreferences(myId(room)));state.note='';
  }
  render();window.scrollTo({top:0,behavior:'instant'});
}
function shell(content){
  const room=currentRoom(),person=room&&state.view!=='home'&&state.view!=='plans'?myMember(room):state.identity;
  const navs=[['home','spark','Discover'],['plans','calendar','My plans'],['preferences','sliders','My preferences'],['privacy','shield','Privacy']];
  const active=id=>state.view===id||(id==='plans'&&state.view==='room');
  return `<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="MeetHalfway home"><span class="brand-symbol">${icon('users')}</span><span class="brand-wordmark">meet<span>halfway</span></span></a><nav aria-label="Main navigation">${navs.map(([id,ico,label])=>`<a href="#${id}" class="nav-item ${active(id)?'active':''}" ${active(id)?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='plans'?`<span class="nav-count">${listRooms().length+state.cloudRooms.length}</span>`:''}</a>`).join('')}</nav><div class="side-note">${icon('shield')}<strong>Your people. Your privacy.</strong><p>Private thoughts stay with you.<br>Good plans bring you together.</p><a href="#privacy" class="text-link">How it works ${icon('chevron')}</a></div><div class="side-bottom">${avatar(person,true)}<div><span class="name">${e(person.name)}</span><p class="muted">${currentConnection()?'Connected':'On this device'}</p></div><button data-action="settings" aria-label="Open settings">${icon('settings')}</button></div></aside><div class="workspace">${navigator.onLine?'':'<div class="network-offline">You’re offline. Saved plans and manual preferences are available.</div>'}<header class="topbar"><span class="topbar-context">${icon(state.view==='home'?'spark':state.view==='room'?'users':'shield')}${{home:'Discover',plans:'Your plans',room:'Your planning room',preferences:'Your preferences',privacy:'Your privacy',settings:'Settings'}[state.view]}</span><a class="brand mobile-brand" href="#home"><span class="brand-symbol">${icon('users')}</span><span class="brand-wordmark">meet<span>halfway</span></span></a><div class="topbar-right"><span class="city-label">${icon('pin')}Toronto ${icon('chevron')}</span>${button('new-room',icon('plus'),'outline small topbar-new','aria-label="Create a plan"')}</div></header><main id="main" class="main ${state.view==='home'?'main-discover':''}" tabindex="-1">${content}${state.view==='home'?'':`<footer class="page-footer"><span>${icon('shield')}Private preferences. Shared possibilities.</span><span>MeetHalfway · Toronto</span></footer>`}</main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navs.map(([id,ico,label])=>`<a href="#${id}" class="${active(id)?'active':''}" ${active(id)?'aria-current="page"':''}>${icon(ico)}${id==='preferences'?'Preferences':label}</a>`).join('')}</nav></div>`;
}
function homeView(){
  return `<section class="discovery-home"><div class="discovery-heading"><span class="discovery-kicker">YOU, THEM & A LITTLE COMMON GROUND</span><h1>Make time for your people.</h1><p>Different tastes. Different budgets. One good plan.</p></div>${orbitMarkup({members:DEMO_MEMBERS,ideas:CATALOG,home:true})}<div class="discovery-bottom"><div class="discovery-quick-actions">${button('open-demo',`${icon('users')} Explore a sample group`,'outline small')}${button('join-invite',`${icon('link')} Join a plan`,'ghost small')}</div><form id="plan-seed-form" class="discovery-composer"><button type="button" data-action="new-room" class="composer-plus" aria-label="Create a new plan">${icon('plus')}</button><label class="sr-only" for="plan-seed">Name your new plan</label><input id="plan-seed" name="seed" maxlength="70" placeholder="What’s the plan? A catch-up, a game night…" autocomplete="off"><span class="composer-hint">New plan</span><button type="submit" class="composer-send" aria-label="Start this plan">${icon('arrow')}</button></form><p class="discovery-disclaimer">Toronto sample ideas · Illustrative photos · ${button('data-info','About these ideas','ghost small')}</p></div></section>`;
}
function plansView(){
  const rooms=[...state.cloudRooms,...listRooms()];
  return `<div class="page-heading"><div><span class="eyebrow">A LITTLE LESS BACK-AND-FORTH</span><h1>Your plans, coming together.</h1><p>Pick up where your people left off.</p></div>${button('new-room',`${icon('plus')} New plan`)}</div><div class="plans-toolbar">${button('join-invite',`${icon('link')} Join with an invitation`,'outline')}</div><div class="plans-grid">${rooms.map(room=>`<article class="panel room-preview"><div class="room-preview-header"><span class="pill ${room.status==='confirmed'?'':'purple'}">${icon(room.status==='confirmed'?'check':'clock')}${statusName(room)}</span><span class="pill subtle">${room.local?'On this device':'Live room'}</span></div><div><h3>${e(room.title)}</h3><p>${icon('calendar')}${formatDate(room.date)} · Toronto</p></div><div class="room-preview-footer"><div class="avatar-stack">${room.members.slice(0,4).map(m=>avatar(m,true)).join('')}<span class="person-count">${room.local?room.members.length:room.memberIds.length} people${room.id==='sample-toronto'?' · sample group':''}</span></div>${button('open-room',`Open plan ${icon('chevron')}`,'outline small',`data-id="${e(room.id)}"`)}</div></article>`).join('')}</div>`;
}
function sampleBanner(room){return room.local?`<div class="mode-banner">${icon('info')}<span>${room.id==='sample-toronto'?'You’re exploring a sample group. Switch people below to try each perspective.':'This plan is saved on this device. Add sample people to explore how group planning works.'} Live rooms connect real people across devices.</span>${button('new-room','Create live room','ghost small')}</div>`:'';}
function roomView(){
  const room=currentRoom();
  if(!room)return `<div class="empty-state">${icon('users')}<h3>${state.cloudError?'We couldn’t open that room.':'Opening your planning room…'}</h3><p>${e(state.cloudError||'Connecting you with your people.')}</p>${button('home','Back to discover','outline')}</div>`;
  const result=rankRoom(room),shortlist=result.eligible.slice(0,3),selected=result.eligible.find(r=>r.candidate.id===state.selected)||shortlist[0];
  if(selected)state.selected=selected.candidate.id;
  const mine=myId(room),host=room.ownerId===mine,ready=readyCount(room),allReady=ready===room.members.length,proposal=room.proposal&&result.eligible.find(r=>r.candidate.id===room.proposal.candidateId);
  const catalogue=roomCatalog(room).map(candidate=>[...result.eligible,...result.rejected].find(r=>r.candidate.id===candidate.id));
  return `${sampleBanner(room)}<div class="room-title-row"><div><a class="text-link" href="#plans">${icon('back')} Your plans</a><h1>${e(room.title)}</h1><div class="room-meta"><span>${icon('calendar')}${formatDate(room.date)}</span><span>${icon('users')}${room.members.length} people</span><span>${icon('pin')}Toronto</span></div></div><div class="room-actions">${host?button('add-option',`${icon('plus')} Add an idea`,'outline'):''}${button('edit-preferences',`${icon('sliders')} My preferences`,'outline')}${button('invite',`${icon('link')} Invite people`)}</div></div>${room.local?'<p class="persona-label">SAMPLE GROUP · Choose a person to try their preferences and vote.</p>':''}<div class="members-strip">${room.members.map(m=>`<${room.local?'button':'div'} class="member-chip ${m.id===mine?'active':''}" ${room.local?`data-action="persona" data-id="${e(m.id)}"`:''}>${avatar(m,true)}<span><span class="member-name">${e(m.name)}${m.id===mine?' · you':''}</span><span class="member-status">${icon(m.card?'check':'clock')}${m.card?'Preferences shared':'Adding preferences'}</span></span></${room.local?'button':'div'}>`).join('')}${room.local&&room.members.length<8?`<button class="member-chip" data-action="add-sample">${icon('plus')}<span class="member-name">Add sample person</span></button>`:''}</div>${room.status==='confirmed'&&proposal?confirmedMarkup(room,proposal):room.proposal&&proposal?votingMarkup(room,proposal):''}${!allReady?`<div class="state-callout">${ready} of ${room.members.length} people have shared preferences. Your shortlist will appear when everyone is ready.</div>`:''}<div class="tabs" role="tablist" aria-label="Plan results"><button class="tab ${state.tab==='shortlist'?'active':''}" data-action="tab" data-id="shortlist" role="tab" aria-selected="${state.tab==='shortlist'}">Common ground <span class="tab-count">${shortlist.length}</span></button><button class="tab ${state.tab==='filtered'?'active':''}" data-action="tab" data-id="filtered" role="tab" aria-selected="${state.tab==='filtered'}">Outside our limits <span class="tab-count">${result.rejected.length}</span></button></div>${state.tab==='shortlist'?`<div class="group-discovery"><section class="group-orbit">${orbitMarkup({members:room.members,ideas:catalogue,selected:state.selected,ready:allReady,local:room.local})}</section><aside class="group-selection">${selected?`<span class="eyebrow selection-eyebrow">${icon('spark')} YOUR COMMON GROUND</span>${candidateMarkup(selected,shortlist.indexOf(selected),room)}<div class="selection-actions">${button('plan-details',`${icon('users')} See the fit for everyone`,'wide',`data-id="${selected.candidate.id}"`)}${button('explain',`${icon('spark')} Explain this shortlist`,'outline wide')}</div><p class="estimate-note">The lowest individual fit comes first. Every shared limit is respected.</p>`:`<div class="empty-state">${icon('users')}<h3>${allReady?'Let’s find a little more room.':'Good plans take everyone.'}</h3><p>${allReady?'No idea meets every requirement. Review the excluded options, then decide together whether to change a limit.':'Each person needs to share their preferences first.'}</p>${button('edit-preferences','Review my preferences','outline')}</div>`}</aside></div>${shortlist.length?`<section class="shortlist-section"><div class="section-title"><div><h2>Good for the whole group.</h2><p class="muted small-text">A few ways to spend a little time together.</p></div></div><div class="shortlist-grid">${shortlist.map((r,i)=>candidateMarkup(r,i,room)).join('')}</div></section>`:''}<details class="travel-disclosure"><summary>${icon('pin')} Somewhere between you <span>Compare estimated travel ${icon('chevron')}</span></summary><div class="room-grid"><div class="travel-breakdown"><h3>${selected?`Getting to ${e(selected.candidate.venue)}`:'A place for the whole group'}</h3>${selected?selected.fits.map(f=>{const m=room.members.find(m=>m.id===f.memberId);return `<div class="travel-row">${avatar(m,true)}<span>${e(m.name)}</span><span class="travel-bar"><span style="width:${Math.min(100,f.travel/60*100)}%"></span></span><strong>~${f.travel} min</strong></div>`;}).join(''):''}<p class="estimate-note">Rough estimates from neighbourhood centres. These are not live routes or arrival times.</p></div>${mapMarkup(room.members,shortlist,state.selected)}</div></details>`:`<div class="shortlist-intro"><div><h2>Everyone’s limits count.</h2><p>These ideas didn’t meet every shared requirement.</p></div></div>${result.rejected.map(r=>`<article class="reject-row"><h3>${e(r.candidate.name)}</h3><p>${r.reasons.map(e).join('<br>')}</p></article>`).join('')}`}<p class="demo-data-note">${room.options?.length?'Activities, prices, hours and access were provided by the host. Verify details before going.':'Toronto sample catalogue. Prices, hours, accessibility and travel are demonstration fixtures.'} Photos are illustrative. ${button('data-info','About these estimates','ghost small')}</p>`;
}
function candidateMarkup(rank,index,room){
  const c=rank.candidate,explanation=state.explainedRevision===room.revision?state.explanations.find(x=>x.id===c.id):null;
  return `<article class="candidate ${c.id===state.selected?'selected':''}"><div class="candidate-main">${activityImage(c)}<div class="candidate-copy"><div class="candidate-top"><span class="eyebrow">${index===0?'YOUR BEST COMMON GROUND':index===1?'A DIFFERENT KIND OF GOOD':'ONE MORE POSSIBILITY'}</span><span class="fit-score" title="Lowest individual fit, out of 100. A planning estimate, not a probability.">${rank.minFit}<span>/100</span></span></div><h3>${e(c.name)}</h3><p class="candidate-venue">${e(c.venue)} · ${e(c.area)}</p><div class="candidate-details"><span>${icon('food')}${c.cost===0?'Free':`~$${c.cost}`} / person</span><span>${icon('clock')}${formatTime(rank.start)} · 90 min</span><span>${icon('train')}~${rank.maxTravel} min max</span></div></div></div>${explanation?`<p class="candidate-explanation">${e(explanation.reason)}${explanation.tradeoff?`<br><strong>The tradeoff:</strong> ${e(explanation.tradeoff)}`:''}</p>`:''}<div class="candidate-bottom"><span>${icon('check')}Within everyone’s shared limits</span><button class="text-link" data-action="plan-details" data-id="${c.id}">Take a closer look ${icon('chevron')}</button></div></article>`;
}
function votingMarkup(room,rank){
  const mine=myId(room),vote=room.votes[mine],valid=vote?.revision===room.proposal.revision;
  return `<section class="voting-panel"><span class="eyebrow">A PLAN ON THE TABLE</span><h2>${e(rank.candidate.name)}</h2><p>${formatDate(room.date)} · ${formatTime(room.proposal.startMinute)} · ${e(rank.candidate.venue)}</p><div class="vote-actions">${[['yes','Count me in', 'check'],['maybe','Let’s discuss','users'],['no','Doesn’t work','close']].map(([choice,label,ico])=>button('vote',`${icon(ico)}${label}`,valid&&vote.choice===choice?'chosen':'',`data-id="${choice}" ${room.status==='confirmed'?'disabled':''}`)).join('')}</div><div class="vote-members">${room.members.map(m=>{const v=room.votes[m.id],active=v?.revision===room.proposal.revision&&v?.candidateId===room.proposal.candidateId;return `<span class="vote-member">${avatar(m,true)}${e(m.name)} · ${active?{yes:'In',maybe:'Discussing',no:'Needs a change'}[v.choice]:'Not voted'}</span>`;}).join('')}</div>${room.ownerId===mine?button('confirm','Everyone’s in. Make it happen.','wide',canConfirm(room)?'':'disabled'):'<p class="estimate-note">The host can confirm once everyone accepts this version of the plan.</p>'}</section>`;
}
function confirmedMarkup(room,rank){return `<section class="confirmed-hero"><span class="eyebrow">${icon('check')} EVERYONE’S IN</span><h2>It’s a plan.</h2><p>${e(rank.candidate.name)} · ${formatDate(room.date)} at ${formatTime(room.proposal.startMinute)}.<br>Meet at ${e(rank.candidate.venue)}. Venue booking and details still need checking.</p>${button('calendar',`${icon('calendar')} Add to calendar`,'lime')}${button('share-plan',`${icon('share')} Share the plan`,'outline')}<div class="feedback-row">${button('feedback','We did this. Leave feedback.','ghost',`style="color:#d0ef8e"`)}</div></section>`;}
function preferenceView(){
  const room=currentRoom(),card=state.draft||structuredClone(DEFAULT_CARD),person=room?myMember(room):state.identity;
  const cap=state.capability;
  return `<div class="page-heading"><div><span class="eyebrow">A LITTLE ABOUT YOU</span><h1>What sounds good?</h1><p>${room?`Preferences for ${e(person.name)} · ${e(room.title)}`:'Your defaults stay on this device until you share a card with a room.'}</p></div></div><div class="form-layout"><section class="panel form-panel"><div class="private-note"><h3>${icon('lock')}Start with a private thought.</h3><p>Tell your device what’s on your mind. Review what it extracts before you share anything.</p><div class="field"><label class="sr-only" for="private-note">Private note</label><textarea id="private-note" name="privateNote" maxlength="2000" placeholder="I’d love something creative, but I need to keep it under $25 this week. Somewhere quiet would be nice.">${e(state.note)}</textarea></div>${button('extract-private',`${icon('spark')} Help me put it into words`,'outline small',cap?.available||cap?.downloadable?'':'disabled')}<p class="capability-note">${icon('shield')}<span>${cap?e(cap.reason||`${cap.provider} is ready on this device.`):'Checking whether this device supports local AI…'}${!cap?.available?' You can edit every preference below.':''} Private notes never fall back to cloud AI.</span></p></div><h2>Your kind of good time.</h2><p>Set your limits and choose a few things you enjoy.</p><div class="field"><label for="area">Your starting neighbourhood ${icon('pin')}</label><select id="area" name="areaId">${AREAS.map(a=>`<option value="${a.id}" ${card.areaId===a.id?'selected':''}>${a.name}</option>`).join('')}</select><p class="field-help">We share a neighbourhood centre, never your exact location.</p></div><div class="field"><label for="spend">Comfortable spend <output class="range-value" id="spend-output">$${card.maxSpend} CAD</output></label><input id="spend" type="range" name="maxSpend" min="0" max="200" step="5" value="${card.maxSpend}"><p class="field-help">A firm per-person limit. We won’t recommend a plan above it.</p></div><div class="two-fields"><div class="field"><label for="travel">Travel limit <output class="range-value" id="travel-output">${card.maxTravel} min</output></label><input id="travel" type="range" name="maxTravel" min="5" max="120" step="5" value="${card.maxTravel}"></div><div class="field"><label for="mode">Getting around</label><select id="mode" name="mode">${[['transit','Public transit'],['walk','Walking'],['bike','Cycling']].map(([id,name])=>`<option value="${id}" ${card.mode===id?'selected':''}>${name}</option>`).join('')}</select></div></div><div class="two-fields"><div class="field"><label for="earliest">Free from</label><select id="earliest" name="earliest">${timeOptions(card.earliest)}</select></div><div class="field"><label for="latest">Need to finish by</label><select id="latest" name="latest">${timeOptions(card.latest)}</select></div></div><div class="field"><span class="field-label">What are you in the mood for?</span><div class="interest-grid">${INTERESTS.map(i=>`<button class="interest ${card.interests.includes(i.id)?'selected':''}" data-action="interest" data-id="${i.id}" aria-pressed="${card.interests.includes(i.id)}">${icon(i.icon)}${i.name}</button>`).join('')}</div></div>${[['quiet','Keep it quiet','Only quieter settings. This is a firm requirement.'],['indoors','Keep it indoors','Weather won’t decide the afternoon.'],['stepFree','Step-free access required','Only options with confirmed access qualify. Unknown access is ruled out.']].map(([id,title,copy])=>`<label class="toggle-row"><span><strong>${title}</strong><p>${copy}</p></span><input type="checkbox" name="${id}" ${card[id]?'checked':''} aria-label="${title}"></label>`).join('')}<div class="form-actions">${button('back-room',room?'Back to the room':'Back to my plans','outline')}${button('save-preferences',`${icon('check')}${room?'Review & share my card':'Save on this device'}`)}</div></section><aside class="sharing-panel"><div class="privacy-badge">${icon('eye')}</div><h2>You’re in control.</h2><p>Here’s what your group would see. Your personal explanation stays private.</p><div id="sharing-preview">${sharingPreview(card)}</div><div class="privacy-boundary"><strong>${icon('lock')}What stays with you</strong>Your private note, the reason behind your budget, and your exact location. Private notes are kept in memory for this screen and aren’t saved.</div></aside></div>`;
}
function sharingPreview(card){return `<ul class="sharing-list"><li>${icon('check')}<span>${e(AREAS.find(a=>a.id===card.areaId)?.name||'Choose a neighbourhood')}<small>Approximate starting area</small></span></li><li>${icon('check')}<span>Up to $${card.maxSpend} CAD per person<small>Shared spending limit</small></span></li><li>${icon('check')}<span>Up to ${card.maxTravel} minutes by ${e(card.mode)}<small>Estimated travel limit</small></span></li><li>${icon('check')}<span>${formatTime(card.earliest)}–${formatTime(card.latest)}<small>Shared availability · Toronto time</small></span></li><li>${icon('check')}<span>${card.interests.map(id=>INTERESTS.find(i=>i.id===id)?.name).map(e).join(', ')||'No interests selected'}</span></li>${card.quiet||card.indoors||card.stepFree?`<li>${icon('check')}<span>${[card.quiet?'Quiet setting':null,card.indoors?'Indoors':null,card.stepFree?'Confirmed step-free access':null].filter(Boolean).join(' · ')}</span></li>`:''}</ul>`;}
function timeOptions(selected){return Array.from({length:37},(_,i)=>360+i*30).map(n=>`<option value="${n}" ${n===selected?'selected':''}>${formatTime(n)}</option>`).join('');}
function privacyView(){return `<div class="page-heading"><div><span class="eyebrow">GOOD COMPANY. CLEAR BOUNDARIES.</span><h1>Bring yourself.<br>Keep your private thoughts.</h1><p>Group planning shouldn’t mean explaining your entire life to the group.</p></div></div><section class="panel section-card"><h2>Just enough to find your halfway.</h2><p>Maybe you’re saving money. Maybe you’re exhausted. Your group needs to know what works for you, and you get to decide how much of the reason to share.</p><div class="how-flow"><div class="how-node">${icon('phone')}<div><strong>A private thought</strong><p>Local AI on a supported device.<br>No cloud fallback for raw notes.</p></div></div><span class="how-connector"></span><div class="how-node">${icon('eye')}<div><strong>Your editable card</strong><p>See the exact preferences.<br>Choose what to share.</p></div></div><span class="how-connector"></span><div class="how-node">${icon('users')}<div><strong>A shared group plan</strong><p>Approved cards coordinate the plan.<br>Everyone has a vote.</p></div></div></div><div class="info-grid"><div class="info-tile">${icon('lock')}<h3>Your words stay here.</h3><p>Private notes are processed only on-device, on supported hardware. If local AI is unavailable, the editable controls work without it. We don’t send those notes to cloud AI.</p></div><div class="info-tile">${icon('pin')}<h3>A neighbourhood is enough.</h3><p>Travel estimates use the centre of the neighbourhood you choose. The group doesn’t need a street address or live location.</p></div><div class="info-tile">${icon('users')}<h3>Limits are limits.</h3><p>Spending, time, travel and access requirements filter the shortlist before ranking. Changing a requirement reopens the decision for everyone.</p></div></div></section><section class="panel section-card"><h2>What’s shared, and with whom?</h2><p>Room members can read approved preference cards: neighbourhood, spending and travel limits, travel mode, interests, availability and access requirements. When you ask cloud AI to explain a shortlist, those approved cards and eligible candidates are sent through Firebase AI Logic. Your private note is excluded. Anyone you invite can see the room’s shared data, so share invitation links with the people you intend to include.</p><div class="promise">${icon('shield')}You review the card before it leaves your device.</div></section><section class="panel section-card"><h2>Where AI actually ran.</h2><p>Real requests get a receipt. Sample recommendations use the same rule-based planning engine, without pretending an AI request happened.</p>${state.receipts.length?state.receipts.map(r=>`<div class="receipt"><div><strong>${r.kind==='on-device'?'On this device':'Cloud explanation'}</strong><span>${e(r.provider)} · ${r.milliseconds.toLocaleString()} ms</span></div><span>${new Date(r.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span></div>`).join(''):'<p class="estimate-note">No AI requests in this session yet.</p>'}</section>`;}
function settingsView(){return `<div class="page-heading"><div><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>Your corner.</h1><p>Your name, this device, and the connection to your people.</p></div></div><section class="panel section-card"><h2>A few essentials.</h2><div class="settings-row"><div><strong>Your display name</strong><p>${e(state.identity.name)} · used when you create or join a room.</p></div>${button('rename','Edit name','outline small')}</div><div class="settings-row"><div><strong>Live rooms</strong><p>${currentConnection()?'Connected to Firebase. You can create and join live rooms.':'Sample rooms are saved on this device. Connect the configured Firebase project to plan across devices.'}</p></div>${button('connect',currentConnection()?'Refresh rooms':'Connect','outline small')}</div><div class="settings-row"><div><strong>Local AI on this ${platform==='web'?'browser':'phone'}</strong><p>${e(state.capability?.reason||'Checking this device…')}</p></div>${button('check-capability','Check again','outline small')}</div><div class="settings-row"><div><strong>Sample group</strong><p>Reset Alex, Maya and Jordan to try the planning experience again.</p></div>${button('reset-demo','Reset sample','outline small')}</div><div class="settings-row"><div><strong>Clear data on this device</strong><p>Removes local sample rooms and saved defaults. Live Firebase room data is unaffected.</p></div>${button('clear-data','Clear local data','danger small')}</div></section><section class="panel section-card"><h2>A note on the Toronto catalogue.</h2><p>The first version uses a clearly labelled sample catalogue. The venue links are provided for verification. Prices, hours, travel and accessibility are fixtures for demonstrating the planning engine. The app doesn’t make reservations or claim live availability.</p><div class="badge-row"><span class="pill subtle">${icon('globe')}Web</span><span class="pill subtle">${icon('phone')}Android</span><span class="pill subtle">${icon('phone')}iPhone</span></div></section>`;}
function render(){
  try{const content={home:homeView,plans:plansView,room:roomView,preferences:preferenceView,privacy:privacyView,settings:settingsView}[state.view]();root.innerHTML=shell(content);}
  catch(error){root.innerHTML=shell(`<div class="empty-state">${icon('info')}<h3>Let’s start fresh.</h3><p>${e(errorMessage(error))}</p>${button('reset-demo','Reset sample room','outline')}</div>`);}
}
function openModal(title,subtitle,content,wide=false){
  modalFocusBefore=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header>${content}</section></div>`;
  document.body.style.overflow='hidden';requestAnimationFrame(()=>modalRoot.querySelector('input,button,select,textarea,a[href]')?.focus());
}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';modalFocusBefore?.focus?.();}
function details(id){
  const room=currentRoom(),rank=rankRoom(room).eligible.find(r=>r.candidate.id===id);if(!rank)return;
  const c=rank.candidate,explanation=state.explainedRevision===room.revision?state.explanations.find(x=>x.id===id):null,host=room.ownerId===myId(room);
  openModal(e(c.name),`${e(c.venue)} · ${e(c.area)}`,`${activityImage(c,'idea-preview-photo')}<p class="detail-copy">${e(c.description)}</p><div class="badge-row"><span class="pill subtle">${c.cost?`~$${c.cost} CAD`:'Free'} per person</span><span class="pill subtle">${formatTime(rank.start)} · 90 minutes</span><span class="pill subtle">${c.indoor?'Indoor':'Outdoor'}</span></div><div class="detail-fits"><p class="field-label">A fit for each person</p>${rank.fits.map(f=>{const m=room.members.find(m=>m.id===f.memberId);return `<div class="detail-fit">${avatar(m,true)}<span>${e(m.name)}</span><div class="fit-track"><span style="width:${f.score}%"></span></div><strong>${f.score}/100</strong></div>`;}).join('')}</div><p class="estimate-note">Scores are planning estimates based on interests, budget headroom and estimated travel. The lowest individual score determines the order first.</p>${explanation?`<p class="detail-copy" style="margin-top:18px">${e(explanation.reason)}<br><strong>The tradeoff:</strong> ${e(explanation.tradeoff)}</p>`:''}<div class="fair-note">${icon('info')}<span>${c.dataSource==='host'?'Costs and hours were provided by your host. Travel is estimated.':'These are sample costs, hours and travel times.'} ${c.stepFree===true?(c.dataSource==='host'?'Step-free access was reported by your host.':'Step-free access is a fictional fixture for this sample venue.'):'Step-free access has not been verified.'} Check current details before going.</span></div><div class="form-actions">${c.url?`<a class="btn outline" href="${e(c.url)}" target="_blank" rel="noopener noreferrer">Visit venue website ${icon('globe')}</a>`:''}${host?button('propose',`${icon('users')}Put this to the group`,'',`data-id="${c.id}" ${room.members.length<2?'disabled':''}`):'<p class="small-text muted">Your host can put this plan to the group.</p>'}</div>`,true);
}
function showNewRoom(seed='Saturday, sorted.'){openModal('Make a little time.','Start a plan. Bring your people. Find your halfway.',`<form id="new-room-form"><div class="field"><label for="new-title">Give your plan a name</label><input id="new-title" name="title" maxlength="70" placeholder="Saturday, sorted." value="${e(seed)}" required></div><div class="two-fields"><div class="field"><label for="new-date">Which day?</label><input id="new-date" name="date" type="date" min="${new Date().toLocaleDateString('en-CA')}" value="${nextSaturday()}" required></div><div class="field"><label for="new-name">Your name</label><input id="new-name" name="name" value="${e(state.identity.name==='You'?'':state.identity.name)}" maxlength="30" placeholder="First name" required></div></div><label class="radio-option"><input name="kind" type="radio" value="live" ${(currentConnection()||state.configured)?'checked':''}><span><strong>Live room</strong><small>Friends join with a private link from their own phones or browsers.</small></span></label><label class="radio-option"><input name="kind" type="radio" value="local" ${(currentConnection()||state.configured)?'':'checked'}><span><strong>Explore on this device</strong><small>Try the planning flow with sample people, saved on this device.</small></span></label><button type="submit" class="btn wide" style="margin-top:10px">${icon('plus')}Make a plan</button></form>`);}
function showAddOption(){
  openModal('Bring an idea to the table.','Add a real option your group is considering. You provide the details.',`<form id="option-form"><div class="field"><label for="option-name">Activity name</label><input id="option-name" name="name" maxlength="70" placeholder="Board games and a catch-up" required></div><div class="two-fields"><div class="field"><label for="option-venue">Venue or meeting place</label><input id="option-venue" name="venue" maxlength="100" required placeholder="Venue name"></div><div class="field"><label for="option-area">Toronto neighbourhood</label><select id="option-area" name="areaId">${AREAS.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></div></div><div class="two-fields"><div class="field"><label for="option-cost">Estimated CAD per person</label><input id="option-cost" name="cost" type="number" min="0" max="200" value="20" required></div><div class="field"><label for="option-tag">Main interest</label><select id="option-tag" name="tag">${INTERESTS.map(i=>`<option value="${i.id}">${i.name}</option>`).join('')}</select></div></div><div class="two-fields"><div class="field"><label for="option-opens">Available from</label><select id="option-opens" name="opens">${timeOptions(960)}</select></div><div class="field"><label for="option-closes">Available until</label><select id="option-closes" name="closes">${timeOptions(1320)}</select></div></div><div class="field"><label for="option-description">What will you do?</label><textarea id="option-description" name="description" maxlength="300" required placeholder="A relaxed game or two, with time to catch up." style="min-height:75px"></textarea></div><div class="field"><label for="option-url">Source or venue link (optional)</label><input id="option-url" name="url" type="url" maxlength="1000" placeholder="https://"></div><div class="field"><label for="option-noise">Setting</label><select id="option-noise" name="noise"><option value="1">Quiet</option><option value="2" selected>Conversation and background noise</option><option value="3">Lively or loud</option></select></div><label class="toggle-row"><span><strong>Indoor activity</strong></span><input type="checkbox" name="indoor" checked></label><label class="toggle-row"><span><strong>I’ve confirmed step-free access</strong><p>Leave this off if access is unknown. This is shared as host-reported information.</p></span><input type="checkbox" name="stepFree"></label><p class="estimate-note">The first activity you add replaces the sample catalogue for this room. Travel uses your selected neighbourhood centre. Adding an activity reopens the group decision.</p><button class="btn wide" type="submit" style="margin-top:18px">${icon('plus')}Add this activity</button></form>`,true);
}
async function openRoom(id){state.persona=id==='sample-toronto'?'alex':state.identity.id;if(location.hash===`#room/${id}`){state.roomId=null;await route();}else nav('room',id);}
async function savePreferences(){
  const card=publicCard(state.draft),room=currentRoom();
  if(!room){rememberPreferences(state.identity.id,card);toast('Your preferences are saved on this device.');nav('home');return;}
  openModal('Your card, your call.','Only the preferences below will be shared with everyone in this room.',`${sharingPreview(card)}<p class="detail-copy">Your private note is excluded. Sharing an updated card reopens the plan and makes earlier votes obsolete.</p><div class="form-actions">${button('close-modal','Keep editing','outline')}${button('approve-share',`${icon('check')}Share this card`)}</div>`);
}
async function performAction(action,el){
  const room=currentRoom(),id=el?.dataset.id;
  if(action==='home')return nav('home');
  if(action==='preview-idea'){
    const candidate=CATALOG.find(c=>c.id===id);if(!candidate)return;
    return openModal(e(candidate.name),`${e(candidate.venue)} · Toronto sample idea`,`${activityImage(candidate,'idea-preview-photo')}<p class="detail-copy">${e(candidate.description)}</p><p class="estimate-note">Illustrative photo, not a verified photo of this venue. Prices, hours, travel and access are sample data. The group’s shared preferences determine which ideas are eligible.</p><div class="form-actions">${button('open-demo','Explore the sample group','outline')}${button('start-from-idea','Make it a plan','',`data-id="${candidate.id}"`)}</div>`);
  }
  if(action==='start-from-idea'){const c=CATALOG.find(c=>c.id===id);return showNewRoom(c?.name);}
  if(action==='preview-person'){closeModal();if(!getRoom('sample-toronto'))createDemo();state.persona=id;state.roomId=null;nav('room','sample-toronto');return;}
  if(action==='orbit-filter'){state.tab='filtered';render();return;}
  if(action==='settings')return nav('settings');
  if(action==='open-demo'){closeModal();if(!getRoom('sample-toronto'))createDemo();return openRoom('sample-toronto');}
  if(action==='open-room')return openRoom(id);
  if(action==='new-room')return showNewRoom();
  if(action==='add-option')return showAddOption();
  if(action==='join-invite')return openModal('There’s room for you.','Paste the invitation your friend shared.',`<form id="join-link-form"><div class="field"><label for="join-link">Invitation link or code</label><input id="join-link" name="invite" maxlength="1500" required placeholder="https://…?invite=…"></div><div class="field"><label for="join-display-name">Your first name</label><input id="join-display-name" name="name" maxlength="30" required value="${e(state.identity.name==='You'?'':state.identity.name)}"></div><button class="btn wide" type="submit">${icon('users')}Join the room</button></form>`);
  if(action==='close-modal')return closeModal();
  if(action==='persona'){state.persona=id;state.explanations=[];render();return;}
  if(action==='tab'){state.tab=id;render();return;}
  if(action==='select-plan'){state.selected=id;render();return;}
  if(action==='plan-details')return details(id);
  if(action==='edit-preferences')return nav('preferences');
  if(action==='back-room')return room?nav('room',room.id):nav('home');
  if(action==='interest'){
    const interests=state.draft.interests;if(interests.includes(id)){if(interests.length===1)return toast('Keep at least one interest.');interests.splice(interests.indexOf(id),1);}else interests.push(id);
    el.classList.toggle('selected');el.setAttribute('aria-pressed',String(interests.includes(id)));document.querySelector('#sharing-preview').innerHTML=sharingPreview(state.draft);return;
  }
  if(action==='save-preferences')return savePreferences();
  if(action==='approve-share')return run(async()=>{
    const card=publicCard(state.draft);rememberPreferences(myId(room),card);
    if(room.local){state.room=shareLocalCard(room.id,myId(room),card);}else await shareCloudCard(room,card,state.identity.name);
    state.note='';state.explanations=[];closeModal();toast('Your card is shared. Your private note stayed on this device.');nav('room',room.id);
  });
  if(action==='extract-private')return run(async()=>{
    const result=await extractPrivate(state.note,state.draft);state.draft=result.card;state.receipts.push(result.receipt);render();toast('Your device prepared a draft. Review it before sharing.');
  });
  if(action==='explain'){
    const result=rankRoom(room),payloadCount=room.members.filter(m=>m.card).length;
    return openModal('A little more context.','Cloud AI can explain the shortlist using approved shared data.',`<p class="detail-copy">This sends the ${payloadCount} approved preference cards and the three eligible plans to Firebase AI Logic. Your private note is excluded. The planning engine has already checked hard requirements; cloud AI explains the result.</p><div class="form-actions">${button('close-modal','Maybe later','outline')}${button('approve-explain',`${icon('cloud')}Explain these plans`)}</div>`);
  }
  if(action==='approve-explain')return run(async()=>{
    const result=await explainShortlist(room,rankRoom(room).eligible);state.receipts.push(result.receipt);if(currentRoom()?.revision!==room.revision)throw new Error('The group changed while the explanation was being prepared. Review the new shortlist and try again.');state.explanations=result.explanations;state.explainedRevision=room.revision;closeModal();render();toast('Explanations are ready. The shortlist and your limits haven’t changed.');
  });
  if(action==='propose')return run(async()=>{
    const rank=rankRoom(room).eligible.find(r=>r.candidate.id===id);if(!rank)throw new Error('That plan no longer fits everyone’s preferences.');
    if(room.members.length<2)throw new Error('Add at least one other person first.');
    if(room.local)state.room=proposeLocal(room.id,myId(room),rank);else await proposeCloud(room,rank);
    closeModal();render();window.scrollTo({top:180,behavior:'smooth'});toast('The plan is on the table. Everyone gets a say.');
  });
  if(action==='vote')return run(async()=>{if(room.local)state.room=voteLocal(room.id,myId(room),id);else await voteCloud(room,id);render();toast(id==='yes'?'You’re in.':id==='maybe'?'The group knows you’d like to discuss it.':'The group knows this needs a change.');});
  if(action==='confirm')return run(async()=>{
    if(!canConfirm(room))throw new Error('Everyone needs to accept the current proposal.');
    if(!rankRoom(room).eligible.some(r=>r.candidate.id===room.proposal.candidateId))throw new Error('This proposal no longer meets the group’s requirements.');
    if(room.local)state.room=confirmLocal(room.id,myId(room));else await confirmCloud(room);render();toast('It’s a plan. Time to make a little time.');
  });
  if(action==='invite'){
    if(room.local)return openModal('Bring your people.','Real people need a live room.',`<p class="detail-copy">This room is an exploration saved on this device. Create a live room to get an invitation link that works on Android, iPhone and web.</p><div class="form-actions">${button('close-modal','Keep exploring','outline')}${button('new-room','Create a live room')}</div>`);
    const config=await readConfig();
    const base=config?.publicWebUrl||(config?.firebase?.projectId?`https://${config.firebase.projectId}.web.app/`:location.origin+location.pathname);
    const url=new URL(base);url.searchParams.set('invite',room.lastJoinInviteId);
    return openModal('Good plans need good company.','Anyone with this link can join, up to eight people.',`<code>${e(url.href)}</code><p class="estimate-note">Invite links expire after seven days. Invitees can see the room’s approved shared cards. Keep the link with the people you want to include.</p><div class="form-actions">${button('copy-invite',`${icon('copy')}Copy invitation`,'outline',`data-url="${e(url.href)}"`)}${button('share-invite',`${icon('share')}Share invitation`,'',`data-url="${e(url.href)}"`)}</div>`);
  }
  if(action==='copy-invite'){await navigator.clipboard.writeText(el.dataset.url);toast('Invitation copied.');return;}
  if(action==='share-invite'){await shareText('MeetHalfway',`Let’s find something everyone can get behind. Join ${room.title}.`,el.dataset.url);return;}
  if(action==='add-sample'){
    const next=DEMO_MEMBERS.find(m=>!room.members.some(x=>x.id===m.id));
    if(!next)return toast('All three sample people are already here. Create a live room for more people.');
    state.room=updateLocal(room.id,r=>{r.members.push(structuredClone(next));r.proposal=null;r.votes={};r.status='gathering';r.revision++;});render();toast(`${next.name} joined as a sample person.`);return;
  }
  if(action==='calendar'){
    const candidate=roomCatalog(room).find(c=>c.id===room.proposal.candidateId),ics=calendarFile(room,candidate);
    if(platform!=='web')return nativeCall('calendar',{ics,title:candidate.name});
    const url=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='meethalfway-plan.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar invitation downloaded.');return;
  }
  if(action==='share-plan'){
    const c=roomCatalog(room).find(c=>c.id===room.proposal.candidateId);await shareText('It’s a plan.',`${c.name}\n${formatDate(room.date)}, ${formatTime(room.proposal.startMinute)}\n${c.venue}, Toronto\nEstimated cost: ${c.cost?`~$${c.cost} CAD per person`:'free'}. Please verify venue details.`,c.url);return;
  }
  if(action==='feedback')return openModal('How did it feel?','A little feedback helps your next plan feel more like you.',`<p class="detail-copy">Feedback updates only your saved interests on this device. It doesn’t rewrite anyone else’s preferences or share a private review.</p><div class="feedback-row">${button('feedback-like',`${icon('heart')}More like this`)}${button('feedback-other','Something different next time','outline')}</div>`);
  if(action==='feedback-like'||action==='feedback-other'){
    const c=roomCatalog(room).find(c=>c.id===room.proposal.candidateId),base=localPreferences(myId(room));
    const interests=action==='feedback-like'?[...new Set([...c.tags,...base.interests])].slice(0,6):base.interests.filter(i=>!c.tags.includes(i));
    rememberPreferences(myId(room),{...base,interests:interests.length?interests:['coffee']});closeModal();toast('Saved on this device for your next plan.');return;
  }
  if(action==='data-info')return openModal('Real boundaries. Sample data.','Know what goes into a recommendation.',`<p class="detail-copy">This Toronto catalogue demonstrates the product with sample per-person prices, opening windows, noise levels and estimated travel. Actual venue details can change. Accessibility is unknown for real venues, so a step-free requirement excludes them; the sample studio is a clearly fictional accessible test option.</p><p class="detail-copy" style="margin-top:15px">Travel uses approximate neighbourhood centres, distance, a travel-mode speed and a buffer. It is not a live TTC route. The score is an estimate of fit, never a guarantee. Venue links let you check details before making a booking.</p>`);
  if(action==='rename')return openModal('What should we call you?','A first name is plenty.',`<form id="rename-form"><div class="field"><label for="display-name">Display name</label><input id="display-name" name="name" maxlength="30" value="${e(state.identity.name)}" required></div><button class="btn wide" type="submit">Save name</button></form>`);
  if(action==='connect')return run(async()=>{await connectFirebase();state.cloudRooms=await listCloudRooms();render();toast('Connected. Your live rooms are ready.');});
  if(action==='check-capability')return run(async()=>{state.capability=await localCapability();render();toast(state.capability.available?'Local AI is ready.':'Capability check complete.');});
  if(action==='reset-demo'){createDemo();if(room?.id==='sample-toronto')state.room=getRoom(room.id);state.explanations=[];render();toast('The sample group is ready to explore again.');return;}
  if(action==='clear-data')return openModal('Clear this device?','Local rooms and saved defaults will be removed.',`<p class="detail-copy">This clears MeetHalfway’s local planning data and display name. Live Firebase room data is unaffected.</p><div class="form-actions">${button('close-modal','Keep my data','outline')}${button('approve-clear','Clear local data','danger')}</div>`);
  if(action==='approve-clear'){clearDeviceData();state.identity=getIdentity();state.room=null;state.roomId=null;state.note='';state.draft=null;state.explanations=[];state.receipts=[];createDemo();closeModal();nav('home');render();toast('Local planning data cleared. A fresh sample is ready.');return;}
}
document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;
  event.preventDefault();if(el.disabled)return;Promise.resolve(performAction(el.dataset.action,el)).catch(error=>toast(errorMessage(error)));
});
document.addEventListener('input',event=>{
  const el=event.target;if(state.view!=='preferences')return;
  if(el.name==='privateNote'){state.note=el.value;return;}
  if(!state.draft||!Object.hasOwn(state.draft,el.name))return;
  state.draft[el.name]=el.type==='checkbox'?el.checked:['maxSpend','maxTravel','earliest','latest'].includes(el.name)?Number(el.value):el.value;
  if(el.name==='maxSpend')document.querySelector('#spend-output').textContent=`$${el.value} CAD`;
  if(el.name==='maxTravel')document.querySelector('#travel-output').textContent=`${el.value} min`;
  document.querySelector('#sharing-preview').innerHTML=sharingPreview(state.draft);
});
document.addEventListener('submit',event=>{
  const form=event.target;if(!['plan-seed-form','new-room-form','rename-form','join-form','join-link-form','option-form'].includes(form.id))return;event.preventDefault();
  if(form.id==='plan-seed-form'){showNewRoom(String(new FormData(form).get('seed')||'').trim().slice(0,70)||'Saturday, sorted.');return;}
  const data=Object.fromEntries(new FormData(form));
  run(async()=>{
    if(form.id==='option-form'){
      const room=currentRoom();if(room.ownerId!==myId(room))throw new Error('Only the host can add activities.');
      const option=validateOption({name:String(data.name).trim(),venue:String(data.venue).trim(),areaId:data.areaId,cost:Number(data.cost),tags:[data.tag],noise:Number(data.noise),indoor:data.indoor==='on',stepFree:data.stepFree==='on'?true:null,description:String(data.description).trim(),url:String(data.url||'').trim(),opens:Number(data.opens),closes:Number(data.closes)});
      if(room.local){
        const id=Array.from({length:12},(_,i)=>`option-${String(i+1).padStart(2,'0')}`).find(id=>!room.options?.some(o=>o.id===id));
        if(!id)throw new Error('This room already has twelve activities.');
        state.room=updateLocal(room.id,r=>{r.options??=[];r.options.push({...option,id});r.revision++;r.status='gathering';r.proposal=null;r.votes={};});
      }else await addCloudOption(room,option);
      state.explanations=[];closeModal();render();return toast('Your activity is on the table. The group’s limits still apply.');
    }
    const name=String(data.name||'').trim().slice(0,30);if(!name)throw new Error('Add your first name.');
    state.identity={...state.identity,name,initials:name.slice(0,2).toUpperCase()};setIdentity(state.identity);
    if(form.id==='rename-form'){closeModal();render();return toast('Your name is saved.');}
    if(form.id==='join-form'||form.id==='join-link-form'){
      let invite=new URLSearchParams(location.search).get('invite');
      if(form.id==='join-link-form'){const input=String(data.invite||'').trim();try{invite=new URL(input).searchParams.get('invite');}catch{invite=input;}}
      const roomId=await joinCloudRoom(invite,name);
      history.replaceState({},'',location.pathname);closeModal();state.roomId=null;nav('room',roomId);return;
    }
    const title=String(data.title||'').trim().slice(0,70),date=String(data.date||'');
    if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date<new Date().toLocaleDateString('en-CA'))throw new Error('Add a name and a date today or later.');
    if(data.kind==='live'){
      const room=await createCloudRoom(title,date,name);closeModal();state.cloudRooms=await listCloudRooms();state.roomId=null;nav('room',room.id);
    }else{
      const room=createLocalRoom(title,date,state.identity);state.persona=state.identity.id;closeModal();state.roomId=null;nav('room',room.id);
    }
  });
});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&modalRoot.children.length){closeModal();return;}
  if(event.key==='Tab'&&modalRoot.children.length){
    const focusable=[...modalRoot.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')],first=focusable[0],last=focusable.at(-1);
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
  }
  if((event.key==='Enter'||event.key===' ')&&event.target.matches('.map-pin')){event.preventDefault();performAction('select-plan',event.target);}
});
window.addEventListener('hashchange',route);
window.addEventListener('storage',()=>{if(state.view!=='preferences')render();});
window.addEventListener('online',render);window.addEventListener('offline',render);
route();
localCapability().then(cap=>{state.capability=cap;if(state.view==='preferences'||state.view==='settings')render();});
// Restore live rooms in the background without replacing an open form.
readConfig().then(async config=>{
  if(!config?.firebase?.projectId)return;
  state.configured=true;
  await connectFirebase();state.cloudRooms=await listCloudRooms();
  if(['home','plans','settings'].includes(state.view)&&!modalRoot.children.length)render();
}).catch(()=>{/* Manual samples remain usable if the connection is unavailable. */});
